const raw = $json.output ?? $json.text ?? $json.response ?? '';

let parsed;

try {
  parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (error) {
  parsed = {
    status: 'error',
    internal_lead_id: $json.internal_lead_id ?? null,
    crm_contact_id: $json.crm_contact_id ?? null,
    crm_deal_id: $json.crm_deal_id ?? null,
    contact_updated: false,
    deal_updated: false,
    stage_updated: false,
    selected_stage_id: null,
    selected_stage_name: null,
    fields_updated: [],
    crm_summary: 'Не удалось распарсить JSON от CRM operator',
    errors: [String(error.message || error)]
  };
}

return [
  {
    json: parsed
  }
];
